package ca.yorku.eecs3311.usedcar;

import ca.yorku.eecs3311.usedcar.app.*;
import ca.yorku.eecs3311.usedcar.domain.*;
import ca.yorku.eecs3311.usedcar.llm.*;
import ca.yorku.eecs3311.usedcar.result.*;
import ca.yorku.eecs3311.usedcar.ui.*;
import com.google.gson.*;
import java.util.*;
import java.io.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static ca.yorku.eecs3311.usedcar.FoundationChecks.check;
import static ca.yorku.eecs3311.usedcar.domain.ClarificationField.*;

/** Offline behavioral tests: real tools, session, facade and interfaces; provider is a test double. */
public final class ClarificationChecks {
    public static class Fake implements LLMClient {
        public int calls;public boolean fail;public String fixed,prompt,schema;
        public String status(){return "OFFLINE FIXTURE";}
        public String generate(String p){throw new AssertionError("Structured generation required");}
        public String generateStructured(String p,String s){calls++;prompt=p;schema=s;if(fail)throw new IllegalStateException("fictional-private-error");
            if(p.startsWith("Generate clarification"))return fixed==null?response(s):fixed;
            if(p.contains("Required checklist: "))return ChecklistChecks.response(p);
            if(p.startsWith("Extract vehicle"))return ListingChecks.fixture().toString();
            return RiskChecks.response(p);
        }
    }
    public static String response(String schema){
        var targets=JsonParser.parseString(schema).getAsJsonObject().getAsJsonObject("properties").getAsJsonObject("questions")
            .getAsJsonObject("items").getAsJsonObject("properties").getAsJsonObject("field").getAsJsonArray("enum");
        var array=new JsonArray();for(var key:targets){var f=ClarificationField.fromKey(key.getAsString());var q=ClarificationQuestion.fallback(f);
            var item=new JsonObject();item.addProperty("field",f.key());item.addProperty("question",q.question());item.addProperty("priority",q.priority());item.addProperty("reason",q.reason());array.add(item);}
        var root=new JsonObject();root.add("questions",array);return root.toString();
    }
    public static Map<String,String> corolla(){var v=PreparationForm.example();v.put("year","2018");v.put("make","Toyota");v.put("model","Corolla");v.put("trim","LE");v.put("mileage","125000");v.put("price","12500");v.put("transmission","AUTOMATIC");v.put("fuelType","GASOLINE");v.put("accident","UNKNOWN");v.put("maintenance","UNKNOWN");v.put("consumption","");v.put("notes","");return v;}
    public static UsedCarApplicationFacade saved(LLMClient llm){var f=RiskChecks.facade(llm);PreparationForm.command(f,corolla()).execute();return f;}
    private static void rejects(Runnable call){try{call.run();}catch(IllegalArgumentException|IllegalStateException expected){return;}throw new AssertionError("Expected rejection");}
    public static void settle(UsedCarApplicationFacade f,ClarificationState s){for(var q:s.batch().questions())if(f.currentClarification().orElseThrow().responses().get(q.field()).status().equals("PENDING"))f.skipClarification(s.cycleId(),q.field(),true);}
    private static List<ClarificationQuestion> parse(String text){return new ResponseParser().parseClarificationQuestions(text,List.of(ACCIDENT,MAINTENANCE));}
    private static JsonObject json(){return JsonParser.parseString(response(ClarificationSchema.json(List.of(ACCIDENT,MAINTENANCE)))).getAsJsonObject();}
    public static void detection(){var llm=new Fake();var f=saved(llm);var before=f.currentVehicle();var s=f.startClarification(false);
        check(s.batch().status().equals("AI_SUCCESS")&&s.batch().questions().size()==3,"Actual F04 gaps must produce three structured questions");
        check(s.batch().questions().get(0).field()==ACCIDENT&&s.batch().questions().get(1).field()==MAINTENANCE,"History gaps must be prioritized");check(f.currentVehicle().equals(before),"LLM cannot update vehicle");}
    public static void parsing(){var q=parse(json().toString());check(q.size()==2&&q.get(0).field()==ACCIDENT,"Valid Gemini-shaped questions must parse");}
    public static void excessive(){var j=json();var a=j.getAsJsonArray("questions");a.add(a.get(0).deepCopy());a.add(a.get(1).deepCopy());rejects(()->parse(j.toString()));}
    public static void duplicates(){var j=json();j.getAsJsonArray("questions").set(1,j.getAsJsonArray("questions").get(0).deepCopy());rejects(()->parse(j.toString()));rejects(()->parse("{\"questions\":[],\"questions\":[]}"));}
    public static void unsupported(){var j=json();j.getAsJsonArray("questions").get(0).getAsJsonObject().addProperty("field","preference");rejects(()->parse(j.toString()));rejects(()->ClarificationField.fromKey("apiKey"));}
    public static void malformed(){for(var s:List.of("","bad","null","[]","{} trailing","{\"questions\":[]}","```json\n"+json()+"\n```"))rejects(()->parse(s));}
    public static void types(){var j=json();j.getAsJsonArray("questions").get(0).getAsJsonObject().addProperty("priority",3);rejects(()->parse(j.toString()));var k=json();k.getAsJsonArray("questions").get(0).getAsJsonObject().remove("field");rejects(()->parse(k.toString()));}
    public static void injection(){var llm=new Fake();var j=json();j.getAsJsonArray("questions").get(0).getAsJsonObject().addProperty("question","Since the car has no accidents, can I change your budget?");llm.fixed=j.toString();var f=saved(llm);var v=f.currentVehicle();var prefs=f.preferences();check(f.startClarification(false).batch().status().equals("FALLBACK"),"Fabricated statements must never be displayed as valid questions");check(f.currentVehicle().equals(v)&&f.preferences().equals(prefs),"Provider content cannot mutate state");}
    public static void fallback(){var llm=new Fake();llm.fail=true;var f=saved(llm);var s=f.startClarification(false);check(s.batch().status().equals("FALLBACK")&&!s.batch().message().contains("fictional-private-error"),"Failure uses useful sanitized fallback");f.submitClarification(s.cycleId(),ACCIDENT,"NO");check(f.currentVehicle().orElseThrow().accidentHistory().equals("NO"),"Fallback answers must work");}
    public static void missingKey(){var f=saved(new GeminiAdapter("",null));check(f.startClarification(false).batch().status().equals("FALLBACK"),"Actual adapter without credential must fall back locally");}
    public static void prompt(){var llm=new Fake();var f=saved(llm);var v=corolla();v.put("notes","fictional-sensitive-note");f.saveVehicle(PreparationForm.vehicle(f,v));f.startClarification(false);check(llm.prompt.contains("Saved preferences")&&llm.prompt.contains("F04")&&!llm.prompt.contains("fictional-sensitive-note")&&!llm.prompt.contains(f.currentVehicle().orElseThrow().id()),"Only relevant labels/preferences, not raw listing notes or IDs, are sent");check(llm.schema.contains("enum")&&llm.schema.contains("maxItems"),"Existing structured interface receives bounded schema");}
    public static void answer(){var f=saved(new Fake());var s=f.startClarification(false);var r=f.submitClarification(s.cycleId(),ACCIDENT,"no");check(r.responses().get(ACCIDENT).status().equals("ANSWERED")&&f.currentVehicle().orElseThrow().accidentHistory().equals("NO"),"Unknown history updated only by validated explicit answer");check(f.currentVehicle().orElseThrow().maintenanceHistory().equals("UNKNOWN"),"Other history preserved");}
    public static void invalidEnum(){var f=saved(new Fake());var s=f.startClarification(false);var before=f.currentVehicle();for(String value:List.of("probably","UNKNOWN","no\nplease",""))rejects(()->f.submitClarification(s.cycleId(),ACCIDENT,value));check(f.currentVehicle().equals(before)&&f.currentClarification().orElseThrow().responses().get(ACCIDENT).status().equals("PENDING"),"Invalid enum leaves data and response unchanged");}
    public static void invalidNumeric(){var f=saved(new Fake());for(var field:List.of(MILEAGE,PRICE,CONSUMPTION,YEAR)){
        var s=f.revisitClarification(field);var before=f.currentVehicle();for(String value:List.of("-1","NaN","1,000","1 km","9999999999999999999999"))rejects(()->f.submitClarification(s.cycleId(),field,value));
        check(f.currentVehicle().equals(before),"Invalid numeric values cannot mutate vehicle");f.skipClarification(s.cycleId(),field,false);}
        rejects(()->YEAR.apply(f.currentVehicle().orElseThrow(),"1000"));rejects(()->MILEAGE.apply(f.currentVehicle().orElseThrow(),"1.5"));}
    public static void skipUnknown(){var f=saved(new Fake());var s=f.startClarification(false);f.skipClarification(s.cycleId(),ACCIDENT,false);f.skipClarification(s.cycleId(),MAINTENANCE,true);check(f.currentVehicle().orElseThrow().accidentHistory().equals("UNKNOWN")&&f.currentVehicle().orElseThrow().maintenanceHistory().equals("UNKNOWN"),"Skip/unknown cannot manufacture negative history");}
    public static void conflict(){var f=saved(new Fake());var s=f.revisitClarification(MILEAGE);var r=f.submitClarification(s.cycleId(),MILEAGE,"130000");check(f.currentVehicle().orElseThrow().mileage()==125000,"Conflict preserves original before choice");String text=ResultFormatter.format(r);check(text.contains("existing=125000")&&text.contains("proposed=130000"),"Conflict displays both values");rejects(()->f.continueClarification(s.cycleId(),false));}
    public static void keep(){var f=saved(new Fake());var s=f.revisitClarification(PRICE);f.submitClarification(s.cycleId(),PRICE,"13000");f.resolveClarification(s.cycleId(),PRICE,false);check(f.currentVehicle().orElseThrow().askingPrice().intValue()==12500&&f.currentClarification().orElseThrow().responses().get(PRICE).status().equals("KEPT"),"Explicit keep preserves price and records choice");}
    public static void accept(){var f=saved(new Fake());var s=f.revisitClarification(MILEAGE);f.submitClarification(s.cycleId(),MILEAGE,"130000");f.resolveClarification(s.cycleId(),MILEAGE,true);check(f.currentVehicle().orElseThrow().mileage()==130000&&f.currentClarification().orElseThrow().history().stream().anyMatch(x->x.contains("ACCEPTED")),"Explicit accept applies validated value and records history");}
    public static void knownUnknown(){var f=saved(new Fake());var s=f.revisitClarification(PRICE);f.skipClarification(s.cycleId(),PRICE,true);check(f.currentVehicle().orElseThrow().askingPrice().intValue()==12500,"Marking known price unknown cannot clear it");}
    public static void history(){var f=saved(new Fake());var s=f.startClarification(false);f.submitClarification(s.cycleId(),ACCIDENT,"NO");f.skipClarification(s.cycleId(),MAINTENANCE,true);var r=f.currentClarification().orElseThrow();check(r.history().stream().anyMatch(x->x.contains("accident -> ANSWERED"))&&r.history().stream().anyMatch(x->x.contains("maintenance -> UNKNOWN")),"History retains question/answer/unknown transitions");try{r.history().clear();throw new AssertionError("Immutable history expected");}catch(UnsupportedOperationException expected){}}
    public static void memory(){var llm=new Fake();var f=saved(llm);var s=f.startClarification(false);settle(f,s);check(f.startClarification(false).cycleId().equals(s.cycleId())&&llm.calls==1,"Reopening does not charge again");var next=f.startClarification(true);check(next.batch().questions().isEmpty()&&llm.calls==1,"Skipped/unknown targets are not repeated automatically");}
    public static void nextCycle(){var llm=new Fake();var f=saved(llm);var v=corolla();v.put("transmission","");v.put("trim","");v.put("fuelType","");f.saveVehicle(PreparationForm.vehicle(f,v));var s=f.startClarification(false);rejects(()->f.startClarification(true));settle(f,s);var next=f.startClarification(true);check(next.batch().questions().size()==3&&next.batch().questions().stream().noneMatch(q->s.responses().containsKey(q.field())),"Explicit next cycle asks only remaining unasked targets");}
    public static void switchVehicle(){var f=saved(new Fake());var s=f.startClarification(false);var v=f.currentVehicle().orElseThrow();f.saveVehicle(new Vehicle("different",v.year(),v.make(),v.model(),v.trim(),v.mileage(),v.askingPrice(),v.transmission(),v.fuelType(),v.accidentHistory(),v.maintenanceHistory(),v.fuelConsumption(),v.notes()));check(f.currentClarification().isEmpty(),"Different vehicle resets memory");rejects(()->f.submitClarification(s.cycleId(),ACCIDENT,"NO"));check(f.startClarification(false).history().size()==3,"History does not leak between vehicles");}
    public static void staleGeneration(){var ref=new AtomicReference<UsedCarApplicationFacade>();var llm=new Fake(){public String generateStructured(String p,String s){var f=ref.get();var v=corolla();v.put("mileage","200000");f.saveVehicle(PreparationForm.vehicle(f,v));return super.generateStructured(p,s);}};var f=saved(llm);ref.set(f);rejects(()->f.startClarification(false));check(f.currentClarification().isEmpty(),"Late provider result cannot attach to changed vehicle");}
    public static void duplicateGeneration(){var ref=new AtomicReference<UsedCarApplicationFacade>();var llm=new Fake(){public String generateStructured(String p,String s){rejects(()->ref.get().startClarification(false));return super.generateStructured(p,s);}};var f=saved(llm);ref.set(f);f.startClarification(false);check(llm.calls==1,"Concurrent generation attempt cannot start a duplicate provider request");}
    public static void resumeIncomplete(){var llm=new Fake();var f=saved(llm);var s=f.startClarification(false);f.submitClarification(s.cycleId(),ACCIDENT,"NO");settle(f,s);var risk=(RiskEvaluation)f.continueClarification(s.cycleId(),false);check(risk.status().equals("INSUFFICIENT_INFORMATION")&&risk.evidence().vehicle().accidentHistory().equals("NO")&&risk.evidence().vehicle().maintenanceHistory().equals("UNKNOWN")&&llm.calls==1,"Real F08 gate uses updated vehicle and preserves unknown without API call");}
    public static void resumeUpdated(){var llm=new Fake();var f=saved(llm);var s=f.startClarification(false);f.submitClarification(s.cycleId(),ACCIDENT,"NO");f.submitClarification(s.cycleId(),MAINTENANCE,"NONE");settle(f,s);var risk=(RiskEvaluation)f.continueClarification(s.cycleId(),false);check(risk.status().equals("AI_SUCCESS")&&llm.prompt.contains("\"maintenanceHistory\":\"NONE\"")&&risk.evidence().vehicle().accidentHistory().equals("NO"),"Updated evidence must reach actual F08 prompt");}
    public static void invalidation(){var llm=new Fake();var f=saved(llm);f.generateCurrentChecklist();f.evaluateCurrentVehicle();var s=f.revisitClarification(PRICE);f.submitClarification(s.cycleId(),PRICE,"14000");check(f.currentChecklist().isPresent(),"Pending conflict is not a mutation");f.resolveClarification(s.cycleId(),PRICE,true);check(f.currentChecklist().isEmpty()&&f.lastRiskEvaluation().isEmpty(),"Accepted edit invalidates old checklist and risk");check(f.evaluateCurrentVehicle().evidence().cost()==null,"Cost cache invalidated");var risk=(RiskEvaluation)f.continueClarification(s.cycleId(),false);check(risk.evidence().cost()!=null&&risk.evidence().cost().purchaseTax().toPlainString().equals("1820.00"),"Resume recalculates using saved assumptions and new price");}
    public static void resumeChecklist(){var f=saved(new Fake());var s=f.startClarification(false);f.submitClarification(s.cycleId(),ACCIDENT,"NO");settle(f,s);var result=(ChecklistEvaluation)f.continueClarification(s.cycleId(),true);check(result.vehicle().accidentHistory().equals("NO")&&result.missing().uncertainFields().contains("Maintenance history")&&f.currentChecklist().isPresent(),"Continue invokes actual F10 with fresh context");}
    public static void listingAmbiguity(){var llm=new Fake();var f=RiskChecks.facade(llm);var original=RiskChecks.complete();original.put("price","19000");f.saveVehicle(PreparationForm.vehicle(f,original));var v=f.currentVehicle();f.analyzeListing(ListingChecks.SOURCE);check(f.currentVehicle().equals(v),"Listing extraction must remain unsaved");var s=f.startClarification(false);check(s.batch().questions().stream().anyMatch(q->q.field()==PRICE),"Unconfirmed listing conflict becomes typed clarification need");settle(f,s);var r=(RiskEvaluation)f.continueClarification(s.cycleId(),false);check(r.status().equals("INSUFFICIENT_INFORMATION")&&r.evidence().missing().uncertainFields().stream().anyMatch(x->x.contains("unresolved listing claim")),"Skipped conflicting listing claims remain explicit uncertainty on resume");}
    public static void cli(){var f=saved(new GeminiAdapter("",null));var bytes=new ByteArrayOutputStream();String script="clarify\nclarify-answer accident invalid\nclarify-answer accident NO\nclarify-unknown maintenance\nclarify-skip consumption\nclarify-show\nclarify\nclarify-continue risk\nclarify-field mileage\nclarify-answer mileage 130000\nclarify-resolve mileage keep\nclarify-field model\nclarify-answer model Corolla Touring\nclarify-resolve model accept\nshow\nquit\n";
        new UsedCarCLI(f,new Scanner(script),new PrintStream(bytes)).run();String text=bytes.toString();check(text.contains("FALLBACK")&&text.contains("ERROR:")&&text.contains("INSUFFICIENT_INFORMATION")&&text.contains("existing=125000")&&text.contains("proposed=130000"),"Actual CLI must show fallback, input errors, conflict and resumed evidence");check(f.currentVehicle().orElseThrow().model().equals("Corolla Touring")&&f.currentVehicle().orElseThrow().mileage()==125000,"CLI preserves answer case and explicit keep");}
    public static void noVehicle(){var f=RiskChecks.facade(new Fake());rejects(()->f.startClarification(false));rejects(()->f.revisitClarification(PRICE));}
    public static void preservedContext(){var f=saved(new Fake());var prefs=f.preferences();var b=RiskChecks.complete();f.saveComparisonVehicle(PreparationForm.comparisonVehicle(f,b));var other=f.comparisonVehicle();var s=f.startClarification(false);f.submitClarification(s.cycleId(),ACCIDENT,"NO");check(f.preferences().equals(prefs)&&f.comparisonVehicle().equals(other),"Vehicle-specific answers preserve buyer profile and Vehicle B");}
    public static void runAll(){listingChecklist();listingFreshness();invalidClaims();detection();parsing();excessive();duplicates();unsupported();malformed();types();injection();fallback();missingKey();prompt();answer();invalidEnum();invalidNumeric();skipUnknown();conflict();keep();accept();knownUnknown();history();memory();nextCycle();switchVehicle();staleGeneration();duplicateGeneration();resumeIncomplete();resumeUpdated();invalidation();resumeChecklist();listingAmbiguity();cli();noVehicle();preservedContext();}

    public static void listingFreshness(){
        var llm=new Fake();var f=RiskChecks.facade(llm);var v=new ResponseParser().parseVehicle(ListingChecks.fixture().toString(),ListingChecks.SOURCE).formValues();v.put("price","19000");f.saveVehicle(PreparationForm.vehicle(f,v));f.generateCurrentChecklist();f.evaluateCurrentVehicle();
        f.analyzeListing(ListingChecks.SOURCE);check(f.currentChecklist().isEmpty()&&f.lastRiskEvaluation().isEmpty(),"New listing uncertainty invalidates dependent results");
        var s=f.startClarification(false);for(var q:s.batch().questions()){if(q.field()==PRICE)f.submitClarification(s.cycleId(),PRICE,"19000");else f.skipClarification(s.cycleId(),q.field(),true);}
        check(f.currentClarification().orElseThrow().responses().get(PRICE).status().equals("ANSWERED"),"Reaffirming current known value needs no false conflict");
        check(((RiskEvaluation)f.continueClarification(s.cycleId(),false)).status().equals("AI_SUCCESS"),"Explicit reaffirmation resolves listing ambiguity and restores evaluation");
    }
    public static void invalidClaims(){
        var j=json();j.getAsJsonArray("questions").get(0).getAsJsonObject().addProperty("reason","This car has complete service records.");rejects(()->parse(j.toString()));
        var k=json();k.getAsJsonArray("questions").get(0).getAsJsonObject().addProperty("priority","Low");rejects(()->parse(k.toString()));
        var extra=json();extra.addProperty("vehicle","overwrite");rejects(()->parse(extra.toString()));
    }

    public static void listingChecklist(){
        var listing=ListingChecks.fixture();for(var field:ClarificationField.values())listing.getAsJsonArray("uncertainFields").add(field.key());
        var llm=new Fake(){public String generateStructured(String p,String s){if(p.startsWith("Extract vehicle"))return listing.toString();return super.generateStructured(p,s);}};
        var f=RiskChecks.facade(llm);RiskChecks.save(f);f.analyzeListing(ListingChecks.SOURCE);var cycle=f.startClarification(false);settle(f,cycle);
        var result=(ChecklistEvaluation)f.continueClarification(cycle.cycleId(),true);
        check(result.status().equals("AI_SUCCESS")&&result.checklist().items().stream().filter(i->i.id().equals("accident-disclosures")).findFirst().orElseThrow().priority().equals("High"),"All listing ambiguities must remain representable as valid checklist IDs and history gaps stay high priority");
        check(result.missing().uncertainFields().contains("unresolved listing claim: Maintenance history"),"Checklist exposes unresolved listing context");
    }
}
